function render_assignments_section_compact(array $assignments, int $classId, array $classes, array $groups, array $subjects, array $teachers): void
{
    $editId = (int)($_GET['edit_assignment'] ?? 0);
    $edit = null;
    foreach ($assignments as $item) {
        if ((int)$item['id'] === $editId) {
            $edit = $item;
        }
    }
    $allLevels = $classId === 0;
    $visible = array_values(array_filter($assignments, fn ($item) => $allLevels || (int)$item['class_id'] === $classId));
    ?><section class="panel assignment-intro"><div class="panel-head"><div><p class="eyebrow">Module administrateur</p><h2>Affectations pédagogiques</h2></div><a class="button <?=$allLevels ? '' : 'secondary'?>" href="?page=structure&amp;section=assignments&amp;class_id=0">Voir toutes les affectations</a></div><form method="get"><input type="hidden" name="page" value="structure"><input type="hidden" name="section" value="assignments"><label>Niveau<select name="class_id" onchange="this.form.submit()"><option value="0" <?=$allLevels ? 'selected' : ''?>>Tous les niveaux</option><?php foreach ($classes as $class):?><option value="<?=$class['id']?>" <?=$classId === (int)$class['id'] ? 'selected' : ''?>><?=e($class['level'])?></option><?php endforeach?></select></label></form></section>
    <details class="panel bulk-assignments"><summary><strong>Créer plusieurs affectations pour un professeur</strong></summary><form method="post"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="bulk_save_assignments"><label>Professeur<select required name="teacher_id"><option value="">Choisir un professeur</option><?php foreach ($teachers as $teacher):?><option value="<?=$teacher['id']?>"><?=e($teacher['name'])?></option><?php endforeach?></select></label><div class="bulk-assignment-grid"><fieldset><legend>Niveaux concernés</legend><div class="student-checklist"><?php foreach ($classes as $class):?><label class="check"><input type="checkbox" name="class_ids[]" value="<?=$class['id']?>"> <?=e($class['level'])?></label><?php endforeach?></div></fieldset><fieldset><legend>Matières enseignées</legend><div class="student-checklist"><?php foreach ($subjects as $subject):?><label class="check"><input type="checkbox" name="subject_ids[]" value="<?=$subject['id']?>"> <?=e($subject['name'])?></label><?php endforeach?></div></fieldset></div><p class="muted">Une affectation « niveau entier » sera créée pour chaque combinaison sélectionnée, avec le coefficient par défaut de la matière.</p><button>Créer les affectations</button></form></details>
    <div class="two-col assignments-layout"><section class="panel"><div class="panel-head"><div><p class="eyebrow"><?=$allLevels ? 'Vue générale' : 'Niveau sélectionné'?></p><h2><?=$allLevels ? 'Toutes les affectations' : count($visible).' affectation'.(count($visible) > 1 ? 's' : '')?></h2></div><span class="badge"><?=count($visible)?></span></div><div class="table-wrap"><table><thead><tr><?php if ($allLevels):?><th>Niveau</th><?php endif?><th>Ordre</th><th>Matière</th><th>Public</th><th>Professeur(s)</th><th>Coef.</th><th>Actions</th></tr></thead><tbody><?php foreach ($visible as $assignment):?><tr><?php if ($allLevels):?><td><strong><?=e($assignment['level'])?></strong></td><?php endif?><td><?=e($assignment['display_order'])?></td><td><strong><?=e($assignment['subject'])?></strong></td><td><?=e($assignment['group_label'] ?: 'Niveau entier')?></td><td><?=e($assignment['teachers'] ?: 'Sans enseignant')?></td><td><?=e($assignment['assignment_coefficient'])?></td><td><span class="table-actions"><a class="icon-button" href="?page=structure&amp;section=assignments&amp;class_id=<?=$classId?>&amp;edit_assignment=<?=$assignment['id']?>" title="Modifier" aria-label="Modifier"><i class="bi bi-pencil-square"></i></a><form method="post" onsubmit="return confirm('Supprimer cette affectation et ses évaluations ?')"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_assignment"><input type="hidden" name="assignment_id" value="<?=$assignment['id']?>"><button class="icon-button danger" title="Supprimer" aria-label="Supprimer"><i class="bi bi-trash"></i></button></form></span></td></tr><?php endforeach?><?php if (!$visible):?><tr><td colspan="<?=$allLevels ? 7 : 6?>" class="empty">Aucune affectation à afficher.</td></tr><?php endif?></tbody></table></div></section>
    <aside class="sticky"><section class="panel"><p class="eyebrow"><?=$edit ? 'Modification' : 'Création rapide'?></p><h2><?=$edit ? 'Modifier l’affectation' : 'Nouvelle affectation'?></h2><?php render_assignment_form($edit, $classes, $groups, $subjects, $teachers, $classId);?><?php if ($edit):?><div class="actions"><a class="button secondary" href="?page=structure&amp;section=assignments&amp;class_id=<?=$classId?>">Annuler</a></div><?php endif?></section><div class="panel"><p class="eyebrow">Organisation</p><h2>Groupes et enseignants</h2><div class="actions"><a class="button secondary" href="?page=structure&amp;section=groups">Composer les groupes</a><?php if (is_admin()):?><a class="button secondary" href="?page=users">Gérer les enseignants</a><?php endif?></div></div></aside></div><?php
}
